// The audit rules in the customer's words, shared by every screen that
// renders a stored action plan — old plans saved before these texts existed
// get the human wording too, because mapping happens at display time.
//
// Who wrote these: this is a fixed dictionary curated with the product owner,
// following how AI crawlers actually read websites (inspired by the
// Cloudflare-style agent-readiness tooling). It is never generated by a
// model at page-render time — the same rule always says the same thing.

type RuleLocale = "en" | "ru";

export type RuleHelpEntry = {
	/** What to do, as a headline. */
	title: string;
	/** Why it matters for AI answers, one plain sentence. */
	why: string;
	/** Concrete steps: what, where on the site, how. */
	steps: string[];
	/** What "done right" looks like, when an example helps. */
	example?: string;
};

