export const PRIORITY_LABELS: Record<string, [string, string]> = {
	NOW: ["Now", "Сейчас"],
	NEXT: ["Next", "Дальше"],
	LATER: ["Later", "Позже"],
};

function entry(locale: RuleLocale, ruleId: string): RuleHelpEntry | null {
	const help = RULE_HELP[ruleId];
	return help ? (locale === "ru" ? help.ru : help.en) : null;
}

export function ruleTitle(locale: RuleLocale, ruleId: string, fallback: string): string {
	return entry(locale, ruleId)?.title ?? fallback;
}

export function ruleHow(locale: RuleLocale, ruleId: string, fallback: string): string {
	return entry(locale, ruleId)?.why ?? fallback;
}

export function ruleSteps(locale: RuleLocale, ruleId: string): string[] {
	return entry(locale, ruleId)?.steps ?? [];
}

export function ruleExample(locale: RuleLocale, ruleId: string): string | null {
	return entry(locale, ruleId)?.example ?? null;
}

/** A ready-to-paste task for a developer or an AI coding agent. */
export function ruleFixTask(locale: RuleLocale, ruleId: string, websiteUrl: string, fallbackTitle: string, fallbackHow: string): string {
	const item = entry(locale, ruleId);
	const title = item?.title ?? fallbackTitle;
	const steps = item?.steps ?? [fallbackHow];
	const example = item?.example;
	return locale === "ru"
		? `Сайт: ${websiteUrl}\nЗадача: ${title}.\nШаги: ${steps.join(" ")}${example ? `\nПример правильного результата: ${example}` : ""}\nВнеси изменение, покажи диф и объясни, что изменилось.`
		: `Site: ${websiteUrl}\nTask: ${title}.\nSteps: ${steps.join(" ")}${example ? `\nExample of done right: ${example}` : ""}\nMake the change, show the diff and explain it.`;
}
